class Allocator()
    var _memory: byte[] = {null, 0}
    var _cursor: int = 0

    fun init(mem: byte[])
        _memory = mem
        _cursor = 0

    @inline
    fun allocate<T>(): &T
        val size := sizeof<T>()
        if _cursor + size > _memory.size()
            return null
        val ptr := &T(&_memory[_cursor])
        _cursor = (_cursor + size + 3) & ~int(3)
        return ptr

    @inline
    fun allocate_array<T>(length: int): T[]
        val size := sizeof<T>() * length
        if _cursor + size > _memory.size()
            return {null, 0}
        val ptr := &T(&_memory[_cursor])
        _cursor = (_cursor + size + 3) & ~int(3)
        return {ptr, length}

    @inline
    fun reset()
        _cursor = 0

#end
